import pyomo.environ as pyo

DATA = {
    "demand": {1: 2, 2: 4, 3: 4, 4: 3, 5: 1, 6: 2, 7: 3},
    "horizon": 7,       # number of days in the schedule
    "work_days": 5,     # every nurse works 5 days in a row
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    horizon = d["horizon"]
    work_days = d["work_days"]
    demand = d["demand"]

    model = pyo.ConcreteModel()

    # Days and possible start days of a consecutive work block
    model.Days = pyo.RangeSet(1, horizon)
    model.Starts = pyo.RangeSet(1, horizon)

    # Continuous nonnegative "number of nurses" (fractional allowed)
    model.x = pyo.Var(model.Starts, within=pyo.NonNegativeReals)

    # Minimise total nurses used
    def obj_rule(m):
        return sum(m.x[s] for s in m.Starts)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Precompute day-start to day-constant coverage multipliers using DATA only.
    # A starter on day s works days t where ((t - s) mod horizon) in {0,...,work_days-1}.
    def duration_map():
        return {
            (s, t): 1 if ((t - s) % horizon) < work_days else 0
            for s in range(1, horizon + 1)
            for t in range(1, horizon + 1)
        }

    covers = duration_map()

    # Coverage for each day, written from DATA-derived constant multipliers.
    def cover_rule(m, t):
        return sum(covers[(s, t)] * m.x[s] for s in m.Starts) >= demand[t]

    model.cover = pyo.Constraint(model.Days, rule=cover_rule)

    return model
